420: 	public function getUserRole(): string {
421: 		if ($this->getCurrentUserIsEntityUser()) {
422: 			return self::ROLE_OWNER;
423: 		}
424: 
425: 		$evaluatedRole = $this->userRole;
426: 
427: 		// If user is not a poll admin (set by normal poll share) and poll group shares exist,
428: 		// iterate over the share types and return the higher role
429: 		if ($this->getPollGroupUserShares() && !$evaluatedRole) {
430: 			// return the higher role of the group shares
431: 			foreach ($this->getPollGroupUserShares() as $shareType) {
432: 				if ($shareType === self::ROLE_ADMIN) {
433: 					$evaluatedRole = self::ROLE_ADMIN;
434: 				}
435: 				return self::ROLE_USER;
436: 			}
437: 		}
438: 
439: 		if ($this->getIsCurrentUserLocked() && $this->userRole === self::ROLE_ADMIN) {
440: 			return self::ROLE_USER;
441: 		}
442: 
443: 		if ($this->userSession->getShareType() === Share::TYPE_PUBLIC) {
444: 			return Share::TYPE_PUBLIC;
445: 		}
446: 
447: 		return $evaluatedRole;
448: 	}
