457: 	/**
458: 	 * Set anonymous setting
459: 	 * If setting has negative value, it is locked and cannot be changed
460: 	 * @param bool|int $value - true for anonymous, false for non-anonymous
461: 	 */
462: 	public function setAnonymousSafe(bool|int $value): void {
463: 		// if anonymous is locked, do not allow changes
464: 		if ($this->getAnonymous() < 0) {
465: 			return;
466: 		}
467: 
468: 		if (!$this->getAllowDeanonymize() && $value > 0) {
469: 			// if the owner of the poll is restricted, lock the anonymous
470: 			// setting once it is set
471: 			// lock anonymous setting by setting it to negative value
472: 			$value = -1;
473: 		}
474: 		$this->setAnonymous((int)$value);
475: 	}
