599: 	public function getDescription(): string {
600: 		return $this->description ?? '';
601: 	}
602: 
603: 	private function getDescriptionSafe(): string {
604: 		return htmlspecialchars($this->getDescription());
605: 	}
606: 
607: 	private function getMaxDate(): int {
608: 		if ($this->maxDate === null) {
609: 			return 0;
610: 		}
611: 		return $this->maxDate;
612: 	}
613: 
614: 	private function setMiscSettingsArray(array $value): void {
615: 		$this->setMiscSettings(json_encode($value));
616: 	}
617: 
618: 	private function getMiscSettingsArray(): array {
619: 		if ($this->getMiscSettings()) {
620: 			return json_decode($this->getMiscSettings(), true);
621: 		}
622: 
623: 		return [];
624: 	}
625: 
626: 	private function getRelevantThreshold(): int {
627: 		return max(
628: 			$this->getCreated(),
629: 			$this->getLastInteraction(),
630: 			$this->getExpire(),
631: 			$this->getMaxDate(),
632: 		);
633: 	}
634: 
635: 	private function getDeletionDate(): int {
636: 		if ($this->getDeleted() > 0 && $this->appSettings->getAutoDeleteEnabled()) {
637: 			return $this->getDeleted() + ($this->appSettings->getAutoDeleteOffsetDays() * 60 * 60 * 24);
638: 		}
639: 		return 0;
640: 	}
641: 
642: 	private function getIsCurrentUserLocked(): bool {
643: 		return boolval($this->isCurrentUserLocked);
644: 	}
645: 
646: 	/**
647: 	 * @param bool|string|int|array $value
648: 	 */
649: 	private function setMiscSettingsByKey(string $key, $value): void {
650: 		$miscSettings = $this->getMiscSettingsArray();
651: 		$miscSettings[$key] = $value;
652: 		$this->setMiscSettingsArray($miscSettings);
653: 	}
654: 
655: 	/**
656: 	 *
657: 	 * Check Permissions
658: 	 *
659: 	 */
660: 
661: 	/**
662: 	 * Request a permission level and get exception if denied
663: 	 * @param string $permission The permission to request
664: 	 * @return Poll Returns the current poll object
665: 	 * @throws ForbiddenException Thrown if access is denied
666: 	 */
667: 	public function request(string $permission): Poll {
668: 		if (!$this->getIsAllowed($permission)) {
669: 			throw new ForbiddenException('denied permission ' . $permission);
670: 		}
671: 		return $this;
672: 	}
673: 
674: 	/**
675: 	 * Check particular rights and inform via boolean value, if the right is granted or denied
676: 	 */
677: 	public function getIsAllowed(string $permission): bool {
678: 		return match ($permission) {
679: 			self::PERMISSION_COMMENT_ADD => $this->getAllowCommenting(),
680: 			self::PERMISSION_COMMENT_DELETE => $this->getAllowDeleteComment(),
681: 			self::PERMISSION_OPTION_ADD => $this->getAllowAddOptions(),
682: 			self::PERMISSION_OPTION_CONFIRM => $this->getAllowConfirmOption(),
683: 			self::PERMISSION_OPTION_CLONE => $this->getAllowCloneOption(),
684: 			self::PERMISSION_OPTION_DELETE => $this->getAllowDeleteOption(),
685: 			self::PERMISSION_OPTIONS_REORDER => $this->getAllowReorderOptions(),
686: 			self::PERMISSION_OVERRIDE => true,
687: 			self::PERMISSION_POLL_ACCESS => $this->getAllowAccessPoll(),
688: 			self::PERMISSION_POLL_EDIT => $this->getAllowEditPoll(),
689: 			self::PERMISSION_POLL_DELETE => $this->getAllowDeletePoll(),
690: 			self::PERMISSION_POLL_ARCHIVE => $this->getAllowEditPoll(),
691: 			self::PERMISSION_POLL_TAKEOVER => $this->getAllowTakeOver(),
692: 			self::PERMISSION_POLL_CHANGE_OWNER => $this->getAllowChangeOwner(),
693: 			self::PERMISSION_POLL_SUBSCRIBE => $this->getAllowSubscribeToPoll(),
694: 			self::PERMISSION_POLL_RESULTS_VIEW => $this->getAllowShowResults(),
695: 			self::PERMISSION_POLL_USERNAMES_VIEW => $this->getAllowEditPoll() || !$this->getAnonymous(),
696: 			self::PERMISSION_VOTE_EDIT => $this->getAllowVote(),
697: 			self::PERMISSION_VOTE_FOREIGN_CHANGE => $this->getAllowChangeForeignVotes(),
698: 			self::PERMISSION_SHARE_ADD => $this->systemSettings->getShareCreateAllowed(),
699: 			self::PERMISSION_SHARE_ADD_EXTERNAL => $this->systemSettings->getExternalShareCreationAllowed(),
700: 			self::PERMISSION_DEANONYMIZE => $this->getAllowDeanonymize(),
701: 			self::PERMISSION_POLL_DOWNLOAD => $this->appSettings->getPollDownloadAllowed() && $this->getAllowDownload(),
702: 			default => false,
703: 		};
704: 	}
705: 
706: 	/**
707: 	 * getIsInvolved - Is current user involved in current poll?
708: 	 * @return bool Returns true, if the current user is involved in the poll
709: 	 *              via personal or group share, as a participant or as the poll owner.
710: 	 */
711: 	public function getIsInvolved(): bool {
712: 		return (
713: 			$this->getIsPollOwner()
714: 			|| $this->getIsParticipant()
715: 			|| $this->getIsPersonallyInvited())
716: 			|| $this->getIsInvitedViaGroupShare();
717: 	}
718: 
719: 	/**
720: 	 * Check, if poll settings is set to open access for internal users
721: 	 */
722: 	private function getIsOpenPoll(): bool {
723: 		return $this->getAccess() === Poll::ACCESS_OPEN && $this->userSession->getIsLoggedIn();
724: 	}
725: 
726: 	/**
727: 	 * getIsParticipant - Is user a participant?
728: 	 * @return bool Returns true, if the current user is already a particitipant of the current poll.
729: 	 */
730: 	private function getIsParticipant(): bool {
731: 		return $this->getCurrentUserVotes() > 0;
732: 	}
733: 
734: 	/**
735: 	 * getIsInvitedViaGroupShare - Is the poll shared via group share?
736: 	 * where the current user is member of. This only affects logged in users.
737: 	 * @return bool Returns true, if the current poll contains a group share with a group,
738: 	 */
739: 	private function getIsInvitedViaGroupShare(): bool {
740: 		if (!$this->userSession->getIsLoggedIn()) {
741: 			return false;
742: 		}
743: 
744: 		return count($this->getGroupSharesForUser()) > 0;
745: 	}
746: 
747: 	private function getGroupSharesForUser(): array {
748: 		return array_filter($this->getGroupShares(), function ($groupName) {
749: 			return ($this->userSession->getCurrentUser()->getIsInGroup($groupName));
750: 		});
751: 	}
752: 	/**
753: 	 * getIsPersonallyInvited - Is the poll shared via user share with the current user?
754: 	 * Checking via user role
755: 	 * @return bool Returns true, if the current poll contains a user role which matches a share type
756: 	 */
757: 	private function getIsPersonallyInvited(): bool {
758: 		return in_array($this->getUserRole(), [
759: 			Poll::ROLE_ADMIN,
760: 			Poll::ROLE_USER,
761: 			Poll::ROLE_EXTERNAL,
762: 			Poll::ROLE_EMAIL,
763: 			Poll::ROLE_CONTACT,
764: 		]);
765: 	}
766: 
767: 	/**
768: 	 * The detailed checks - For the sake of readability, the queries and selections
769: 	 * were kept detailed and with low complexity
770: 	 */
771: 
772: 	/**
773: 	 * Checks, if the user has delegated admin rights to edit poll settings via share
774: 	 */
775: 	private function getIsDelegatedAdmin(): bool {
776: 		return $this->getUserRole() === Poll::ROLE_ADMIN
777: 			&& !$this->getIsCurrentUserLocked();
778: 	}
779: 
780: 	/**
781: 	 * Checks, if user is allowed to edit the poll configuration
782: 	 **/
783: 	private function getAllowEditPoll(): bool {
784: 		// Console has god mode
785: 		if (defined('OC_CONSOLE')) {
786: 			return true;
787: 		}
788: 
789: 		// owner is always allowed to edit the poll configuration
790: 		if ($this->getIsPollOwner()) {
791: 			return true;
792: 		}
793: 
794: 		// user has delegated owner rights
795: 		if ($this->getIsDelegatedAdmin()) {
796: 			return true;
797: 		}
798: 
799: 		// deny edit rights in all other cases
800: 		return false;
801: 	}
802: 
803: 	private function getAllowTakeOver(): bool {
804: 		return $this->userSession->getCurrentUser()->getIsAdmin();
805: 	}
806: 
807: 	/**
808: 	 * Checks, if user is allowed to edit the poll configuration
809: 	 **/
810: 	private function getAllowChangeOwner(): bool {
811: 		return $this->getAllowEditPoll()
812: 		|| $this->userSession->getCurrentUser()->getIsAdmin();
813: 	}
814: 
815: 	/**
816: 	 * Checks, if user is allowed to access (view) poll
817: 	 */
818: 	private function getAllowAccessPoll(): bool {
819: 		// edit rights include access to poll
820: 		if ($this->getAllowEditPoll()) {
821: 			return true;
822: 		}
823: 
824: 		// No further access to poll, if it is deleted
825: 		if ($this->getDeleted()) {
826: 			return false;
827: 		}
828: 
829: 		// grant access if poll poll is an open poll (for logged in users)
830: 		if ($this->getIsOpenPoll() && $this->userSession->getIsLoggedIn()) {
831: 			return true;
832: 		}
833: 
834: 		// grant access if user is involved in poll in any way
835: 		if ($this->getIsInvolved()) {
836: 			return true;
837: 		}
838: 
839: 		$share = $this->userSession->getShare();
840: 		// return check result of an existing valid share for this user
841: 		return boolval($share->getId() && $share->getPollId() === $this->getId());
842: 	}
843: 
844: 	/**
845: 	 * Checks, if user is allowed to delete the poll
846: 	 * includes the right to archive and take over
847: 	 **/
848: 	private function getAllowDeletePoll(): bool {
849: 		if ($this->getAllowEditPoll()) {
850: 			// users with edit rights are allowed to delete the poll
851: 			return true;
852: 		}
853: 
854: 		// additionally site admins are allowed to delete polls, in all other cases deny poll deletion right
855: 		return $this->userSession->getCurrentUser()->getIsAdmin();
856: 	}
857: 
858: 	/**
859: 	 * Checks, if user is allowed to add add vote options
860: 	 **/
861: 	private function getAllowAddOptions(): bool {
862: 		// Edit right includes adding new options
863: 		if ($this->getAllowEditPoll()) {
864: 			return true;
865: 		}
866: 
867: 		// deny, if user has no access right to this poll
868: 		if (!$this->getAllowAccessPoll()) {
869: 			return false;
870: 		}
871: 
872: 		// deny, if user is not allowed to vote
873: 		if (!$this->getAllowVote()) {
874: 			return false;
875: 		}
876: 
877: 		// public shares are not allowed to add options
878: 		if ($this->userSession->getShare()->getType() === Share::TYPE_PUBLIC) {
879: 			return false;
880: 		}
881: 
882: 		// Request for option proposals is expired, deny
883: 		if ($this->getProposalPeriodIsExpired()) {
884: 			return false;
885: 		}
886: 
887: 		// Locked Users are not allowed to add options
888: 		if (boolval($this->getIsCurrentUserLocked())) {
889: 			return false;
890: 		}
891: 
892: 		// Allow, if poll requests proposals
893: 		return $this->getAllowProposals() === Poll::PROPOSAL_ALLOW;
894: 	}
895: 
896: 	private function getAllowCloneOption(): bool {
897: 		return $this->getAllowEditPoll();
898: 	}
899: 
900: 	/**
901: 	 * Is current user allowed to delete options from poll
902: 	 */
903: 	private function getAllowDeleteOption(): bool {
904: 		return $this->getIsPollOwner() || $this->getIsDelegatedAdmin();
905: 	}
906: 
907: 	/**
908: 	 * Is current user allowed to confirm options
909: 	 */
910: 	private function getAllowConfirmOption(): bool {
911: 		return $this->getAllowEditPoll() && $this->getIsExpired();
912: 	}
913: 
914: 	/**
915: 	 * Is current user allowed to confirm options
916: 	 */
917: 	private function getAllowReorderOptions(): bool {
918: 		return $this->getAllowEditPoll() && !$this->getIsExpired() && $this->getType() === Poll::TYPE_TEXT;
919: 	}
920: 
921: 	/**
922: 	 * Checks, if the current user is the poll owner
923: 	 **/
924: 	public function getIsPollOwner(): bool {
925: 		return ($this->getUserRole() === Poll::ROLE_OWNER);
926: 	}
927: 
928: 	/**
929: 	 * Permission checks
930: 	 */
931: 
932: 	/**
933: 	 * Checks, if user is allowed to see and write comments
934: 	 **/
935: 	private function getAllowCommenting(): bool {
936: 		if ($this->getAllowEditPoll()) {
937: 			// users with edit rights are allowed to comment
938: 			return true;
939: 		}
940: 
941: 		// user has no access right to this poll
942: 		if (!$this->getAllowAccessPoll()) {
943: 			return false;
944: 		}
945: 
946: 		// public shares are not allowed to comment
947: 		if ($this->userSession->getShare()->getType() === Share::TYPE_PUBLIC) {
948: 			return false;
949: 		}
950: 
951: 		// public shares are not allowed to comment
952: 		if (boolval($this->getIsCurrentUserLocked())) {
953: 			return false;
954: 		}
955: 
956: 		// return the poll setting for comments
957: 		return (bool)$this->getAllowComment();
958: 	}
959: 
960: 	/**
961: 	 * Checks, if user is allowed to delete comments from poll
962: 	 **/
963: 	private function getAllowDeleteComment(): bool {
964: 		return $this->getAllowEditPoll();
965: 	}
966: 
967: 	/**
968: 	 * Checks, if poll owner is allowed to change votes
969: 	 **/
970: 	private function getAllowChangeForeignVotes(): bool {
971: 		return $this->getAnonymous() > -1 && $this->getAllowEditPoll() && $this->getUser()->getIsUnrestrictedPollOwner();
972: 	}
973: 
974: 	/**
975: 	 * Checks, if poll owner is allowed to deanonymize votes
976: 	 **/
977: 	private function getAllowDeanonymize(): bool {
978: 		// Deanonymization is only allowed,
979: 		// if the anonymize setting is not locked
980: 		// and the current user is allowed to edit the poll
981: 		// and the owner of the poll is unrestricted
982: 		return $this->getAnonymous() > -1
983: 			&& $this->getAllowEditPoll()
984: 			&& $this->getUser()->getIsUnrestrictedPollOwner();
985: 	}
986: 
987: 	/**
988: 	 * Checks, if user is allowed to vote
989: 	 **/
990: 	private function getAllowVote(): bool {
991: 		// user has no access right to this poll
992: 		if (!$this->getAllowAccessPoll()) {
993: 			return false;
994: 		}
995: 
996: 		// Only external, user or admin shares are allowed to vote
997: 		// All other external types have to register first
998: 		if (!in_array($this->userSession->getCurrentUser()->getType(), [UserBase::TYPE_EXTERNAL, UserBase::TYPE_USER, UserBase::TYPE_ADMIN])) {
999: 			return false;
1000: 		}
1001: 
1002: 		// Locked users are not allowed to vote
1003: 		if (boolval($this->getIsCurrentUserLocked())) {
1004: 			return false;
1005: 		}
1006: 
1007: 		// deny votes, if poll is expired
1008: 		return !$this->getIsExpired();
1009: 	}
1010: 
1011: 	/**
1012: 	 * Checks, if user is allowed to subscribe to updates
1013: 	 **/
1014: 	private function getAllowSubscribeToPoll(): bool {
1015: 		// user with access to poll are always allowed to subscribe
1016: 		if (!$this->getAllowAccessPoll()) {
1017: 			return false;
1018: 		}
1019: 
1020: 		return $this->userSession->getCurrentUser()->getHasEmail();
1021: 	}
1022: 
1023: 	/**
1024: 	 * Checks, if user is allowed to see results of current poll
1025: 	 **/
1026: 	private function getAllowShowResults(): bool {
1027: 		// edit rights include access to results
1028: 		if ($this->getAllowEditPoll()) {
1029: 			return true;
1030: 		}
1031: 
1032: 		// no access to poll, deny
1033: 		if (!$this->getAllowAccessPoll()) {
1034: 			return false;
1035: 		}
1036: 
1037: 		// show results, when poll is closed
1038: 		if ($this->getShowResults() === Poll::SHOW_RESULTS_CLOSED && $this->getIsExpired()) {
1039: 			return true;
1040: 		}
1041: 		// return poll settings
1042: 		return $this->getShowResults() === Poll::SHOW_RESULTS_ALWAYS;
1043: 	}
1044: 
1045: }

